upload_auto_resume_hint:
  "اگر بارگذاری در میانه‌ی انتقال قطع شد — بیشتر اوقات چون payload PS5 کرش کرده — به‌طور خودکار payload را دوباره بفرست و از جایی که رها شد ادامه بده، چند بار تلاش کن قبل از تسلیم. مشکلات مرگبار مثل تمام شدن فضای PS5 فوراً متوقف می‌شوند. به‌طور پیش‌فرض روشن.",
upload_rest_after: "پس از پایان بارگذاری‌ها PS5 را در حالت استراحت قرار بده",
upload_rest_after_hint:
  "وقتی صف بارگذاری یک کنسول تمام شد، از آن بخواه به حالت استراحت برود — برای صف یک‌شبه مناسب است. تنها وقتی فعال می‌شود که حداقل یک بارگذاری واقعاً کامل شده باشد (نه پس از توقف یا اجرای همه‌ناموفق). به‌طور پیش‌فرض خاموش. Standby ممکن است روی برخی فریم‌ورها در دسترس نباشد؛ اگر رد شود اعلانی می‌گیرید.",
