"pkg.reason.stream_unreachable": "PS5 هرگز به این کامپیوتر برای واکشی بسته نرسید. ps5upload را از فایروال این کامپیوتر عبور دهید (در ویندوز، برای هر دو شبکه Private و Public)، کامپیوتر و PS5 را با VPN خاموش روی یک شبکه نگه دارید، و Proxy Server PS5 را روی «Do Not Use» بگذارید. بارگذاری و نصب بدون این اتصال کار می‌کند.",
"pkg.reason.staged_refused": "PS5 این بسته را از حافظه‌ی خودش رد کرد. پیش از نسخه‌ی 6.3.1 یک باگ در ps5upload باعث این می‌شد که برطرف شده است، پس دیگر نباید رخ دهد؛ مشکل از فایل نیست. اگر دوباره آن را دیدید، بسته را با استریم و نصب از یک کامپیوتر نصب کنید (برنامه‌ی دسکتاپ، یا رابط وب روی یک سرور خانگی) و یک گزارش باگ برای ما بفرستید.",
"pkg.reason.stream_proxy": "تنظیم پروکسی PS5 استریم را مسدود کرد. در تنظیمات پیشرفته‌ی شبکه‌ی PS5، Proxy Server را روی «Do Not Use» بگذارید، یا از بارگذاری و نصب استفاده کنید که بسته را از حافظه‌ی محلی PS5 می‌خواند.",
