"joberr.ava1_stalled": "انتقال دیگر پیشرفتی نداشت (منبع ارسال داده را متوقف کرد). دوباره تلاش کنید؛ اگر تکرار شد، درایو منبع یا اشتراک شبکه را بررسی کنید.",
"joberr.zip_unsupported": "این فایل .zip از ویژگی‌ای استفاده می‌کند که بارگذار نمی‌تواند آن را استریم کند (رمزگذاری، روش فشرده‌سازی غیر از Deflate یا Stored، یا مسیر فایل ناایمن یا تکراری). آن را روی کامپیوتر خود استخراج کنید و به‌جایش پوشه را بارگذاری کنید.",
"joberr.sevenz_unsupported": "این فایل .7z از روش فشرده‌سازی یا ویژگی‌ای استفاده می‌کند که بارگذار نمی‌تواند آن را استریم کند. آن را روی کامپیوتر خود استخراج کنید و به‌جایش پوشه را بارگذاری کنید.",
"joberr.sevenz_unsupported_layout": "این فایل .7z داخل یک بلوک فشرده‌ی یکپارچه، میان فایل‌هایش پوشه یا فایل خالی دارد؛ چیدمانی که بارگذار نمی‌تواند استریم کند. آن را دوباره با 7-Zip بسته‌بندی کنید، یا استخراجش کنید و پوشه را بارگذاری کنید.",
"joberr.rar_unsupported": "این فایل .rar مسیر فایل تکراری یا ناایمن دارد، یا از ویژگی‌ای استفاده می‌کند که بارگذار نمی‌تواند استریم کند. آن را روی کامپیوتر خود استخراج کنید و به‌جایش پوشه را بارگذاری کنید.",
"pairing_title": "جفت‌سازی با PS5 شما",
"pairing_enter_intro": "{name} درخواست جفت‌سازی با این برنامه را دارد. کدی را که روی PS5 نمایش داده می‌شود وارد کنید.",
