"fakegame.fw.launch": "بسته‌های بازی جعلی PS5 روی فریم‌ور بالاتر از {last} قابل اجرا نیستند (این کنسول روی {fw} است). اگر این بازی از یک بسته‌ی جعلی نصب شده، به همین دلیل اجرا نمی‌شود. بسته‌های PS4 مشکلی ندارند.",
