"pkg.sony_80b21104": "PS5 این بسته را نپذیرفت (0x80B21104). اگر بسته‌های دیگر روی این کنسول نصب می‌شوند، مشکل از همین فایل است: بیشتر وقت‌ها بسته یک بازی جدید که با ابزارهایی جدیدتر از آنچه فریمور این کنسول می‌فهمد ساخته شده، یا بسته‌ای که نسخه با امضای جعلی (FPKG) نیست. از بسته‌ای که برای فریمور شما ساخته شده (بک‌پورت) استفاده کنید، یا بازی را بدون نصب‌کننده نصب کنید: پوشه بازی، یا ایمیج بازی (.exfat یا .ffpfsc) برای ShadowMount+ را با بارگذاری کپی کنید.",
