drive_subtitle: "پوشه‌ای که روی رایانه‌ها، گوشی‌ها و Docker شما یکسان می‌ماند و خانه‌اش روی این کنسول است. هر جا فایلی اضافه کنید، به همهٔ دستگاه‌های درایو می‌رسد.",
