drive_how_1: "تا وقتی کمک‌یار کنسول در حال اجراست، هر دستگاه در درایو هر نیم دقیقه با پوشهٔ خانه‌اش روی کنسول همگام می‌شود. Docker بدون باز بودن هیچ برنامه‌ای به کار ادامه می‌دهد.",
drive_how_2: "تغییر هم‌زمان در دو جا: هر دو نگه داشته می‌شوند و یکی به \"(تعارض از …)\" تغییر نام می‌یابد.",
drive_how_3: "فایل‌های حذف‌شده ۳۰ روز به پوشهٔ .ps5upload-trash درایو می‌روند. حذف هم‌زمان فایل‌های زیاد منتظر تأیید شما می‌ماند.",
drive_how_4: "پوشه‌ای که فایل .ps5upload-mesh خود را ندارد (دیسکی جداشده) آفلاین به حساب می‌آید و هرگز حذف‌شده به حساب نمی‌آید.",
