about_feat_console_title: "کنترل کنسول",
about_feat_convert_body: "پوشه یا ایمیج یک بازی را به بسته‌ی قابل نصب تبدیل کنید، یا یک پوشه را به ایمیج بازی‌ای که ShadowMount+ متصل می‌کند.",
about_feat_convert_title: "تبدیل بازی‌ها",
about_feat_install_body: "بسته‌های .pkg PS4 و بسته‌های جعلی PS5 (پایه، به‌روزرسانی، DLC) از این کامپیوتر، یک اشتراک NAS، درایو USB یا یک لینک. اگر PS5 یک روش را رد کند، برنامه روش دیگری پیشنهاد می‌دهد.",
