about_feat_payloads_body: "فایل‌های ELF پی‌لود را از کاتالوگ یا فایل‌های خودتان، یکی‌یکی یا به‌صورت لیست پخش، به لودر کنسول بفرستید.",
about_feat_payloads_title: "Payloadها",
about_feat_saves_body: "از داده‌ی ذخیره‌ی بازی در یک فایل .zip روی این کامپیوتر نسخه‌ی پشتیبان بگیرید و بعداً بازیابی کنید.",
about_feat_saves_title: "داده‌ی ذخیره",
activity_cancel_tooltip: "لغو این عملیات",
activity_clear_shown_confirm_body: "ورودی‌های تمام‌شده‌ی فهرست‌شده در اینجا (انجام‌شده، ناموفق، متوقف‌شده) حذف می‌شوند. تاریخچه‌ی کنسول‌های دیگر و هر چیزی که هنوز در حال اجراست حفظ می‌شود. برای حذف یک ردیف، از دکمه‌ی سطل زباله‌ی آن استفاده کنید.",
activity_clear_shown_confirm_title: "این تاریخچه پاک شود؟",
activity_view_history: "تاریخچه",
"always_overwrite_hint_v2": "وقتی مقصد یک ارسال از قبل فایل دارد، تأیید را رد کن. خاموش بگذارید تا پیام بازنویسی / ادامه / لغو را ببینید.",
audit_empty_v2: "هنوز چیزی ثبت نشده. اقدامات برق (بیدار کردن، حالت استراحت، راه‌اندازی مجدد، خاموش کردن)، حذف‌ها، لغو ثبت‌ها، حذف نصب‌ها و نصب‌ها همین‌طور که انجامشان می‌دهید اینجا ظاهر می‌شوند.",
audit_log_description_v3: "سابقه‌ای که در این برنامه روی این کامپیوتر نگه داشته می‌شود از اقدامات برق، حذف‌ها، لغو ثبت‌ها، حذف نصب‌ها و نصب‌ها. ۲۵۶ مورد جدیدتر نگه داشته و قدیمی‌ترها کنار گذاشته می‌شوند؛ دکمه‌ی پاک کردن وجود ندارد، اما پاک کردن داده‌های برنامه یا حافظه‌ی مرورگر آن را پاک می‌کند. ۱۰۰ مورد آخر نمایش داده می‌شود.",
autoloader_title_v2: "لیست پخش هنگام اتصال",
