backup_explain_v2: "فایل‌ها را در یک اسنپ‌شات روی حافظه‌ی خود کنسول کپی می‌کند تا بعداً بتوانید برشان گردانید. یکی از گزینه‌های رایج زیر را انتخاب کنید یا مسیر خودتان را بنویسید.",
backup_limit_depth: "پوشه‌هایی که بیش از {n} سطح پایین‌تر از پوشه‌ی انتخابی شما هستند نادیده گرفته می‌شوند.",
backup_limit_flatten: "فایل‌ها با مسیرشان ذخیره می‌شوند و هر / به _ تبدیل می‌شود، پس دو مسیر متفاوت ممکن است به یک نام برسند (a/b_c و a_b/c) و فقط یکی از آن‌ها نگه داشته شود.",
backup_limit_keep: "فقط {n} اسنپ‌شات جدیدتر از هر نام نگه داشته می‌شود؛ ساختن یکی دیگر قدیمی‌ترین را حذف می‌کند.",
backup_subtitle_v3: "فایل‌ها و پوشه‌ها را در اسنپ‌شاتی روی خود PS5 کپی کنید و بعداً برگردانید. چیزی به این کامپیوتر کپی نمی‌شود. برای ذخیره‌ی بازی‌ها از «داده‌ی ذخیره» استفاده کنید.",
