beta_features_hint_v2: "صفحه‌های در حال توسعه را، در صورت وجود، به نوار کناری اضافه می‌کند. قابل استفاده‌اند اما هنوز قابل اعتماد نیستند و ممکن است تغییر کنند یا حذف شوند.",
bringup_desc_v2: "برای هر بار روشن شدن، پس از تنظیم لیست‌های پخش در Payloadها: لیست پخش راه‌اندازی شما (kstuff، ShadowMount+…) را اجرا می‌کند، کمک‌یار را همانند مرحله‌ی ۲ می‌فرستد و سپس لیست پخش بارگذاری خودکار را اجرا می‌کند.",
changelog_description_v2: "یادداشت‌های انتشار هر نسخه‌ی ps5upload تا همین نسخه، همراه با برنامه. انتشارهای جدیدتر و دانلودهایشان در GitHub هستند.",
