cheats_reapply_hint: "فایل‌های تقلب روی PS5 را دوباره بخوان و موارد روشن را دوباره اعمال کن. کنسول یک اعلان روی تلویزیون نشان می‌دهد.",
cheats_search_hint_v2: "نام بازی یا شناسه‌ی عنوان (مثلاً PPSA07631 یا CUSA00900) را وارد کنید و جستجو را بزنید",
