companion_suggest_body_v2: "ps5upload با kstuff (اکسپلویت کرنل)، ShadowMount+ (اتصال خودکار نسخه‌های پشتیبان بازی) و ده‌ها payload هوم‌برو دیگر کار می‌کند. Payloadها → کاتالوگ آن‌ها را با یک کلیک می‌فرستد.",
companion_suggest_open_payloads: "باز کردن Payloadها",
connection_first_run_nudge_body_v2: "جادوگر راه‌اندازی kstuff و ShadowMount+ را دانلود و ارسال می‌کند و سپس کمک‌یار را، به ترتیب درست. اگر کنسول شما خودش kstuff را بارگذاری می‌کند (یک autoloader، etaHEN)، مرحله‌ی ۲ در زیر فقط کمک‌یار را می‌فرستد.",
connection_step2_which: "این فقط کمک‌یار را می‌فرستد. برای بارگذاری kstuff و ShadowMount+ هم، بار اول از جادوگر راه‌اندازی استفاده کنید، یا پس از تنظیم لیست‌های پخش، در هر بار روشن شدن از «راه‌اندازی سریع» در زیر.",
