fakelibs_set_remove_confirm_body: "«{label}» از مجموعه‌ی کتابخانه‌ها حذف می‌شود. بازی‌هایی که از قبل backport شده‌اند کتابخانه‌هایشان را نگه می‌دارند، اما backport کردن بازی‌ای که به این مجموعه نیاز دارد مستلزم افزودن دوباره‌ی آن است.",
fakelibs_set_remove_confirm_title: "این مجموعه‌ی کتابخانه حذف شود؟",
first_run_description_v3: "آنچه بیشتر پیکربندی‌ها لازم دارند را به ترتیب درست بارگذاری می‌کند: kstuff (امکان نصب و اجرای بسته‌های جعلی)، ShadowMount+ (قرار دادن ایمیج‌ها و پوشه‌های بازی روی صفحهٔ اصلی PS5) و کمک‌یار خود ps5upload. پس از راه‌اندازی مجدد PS5، صفحه‌ی اتصال دوباره این جادوگر را پیشنهاد می‌دهد.",
