game_activity_subtitle_v3: "چه چیزی روی این PS5 بازی شده و چه مدت. زمان بازی ردیابی‌شده را کمک‌یار ps5upload روی کنسول می‌شمارد؛ زمان بازی کنسول از سوابق خود کنسول خوانده می‌شود.",
hardware_description_v2: "اطلاعات سیستم، مدت روشن بودن و حافظه هنگام اتصال کمک‌یار هر ۵ ثانیه خودکار به‌روز می‌شوند. دمای لحظه‌ای و فرکانس CPU در صورت درخواست خوانده می‌شوند — روی «خواندن سنسورها» کلیک کنید. فرم‌ور خرده‌فروشی همه‌ی مقادیر را در اختیار نمی‌گذارد (مثلاً مصرف CPU)؛ آن‌ها با خط تیره نمایش داده می‌شوند.",
