keep_ps5_awake_mode_hint_v2: "تایمر آماده‌به‌کار خودکار PS5 را به‌طور دوره‌ای بازنشانی می‌کند تا به حالت استراحت نرود. «هنگام بارگذاری و نصب» از بارگذاری‌های طولانی محافظت می‌کند (دلیل رایج شکست بارگذاری‌ها؛ پیش‌فرض). «همیشه هنگام اتصال» تا وقتی برنامه باز است هر کنسولی را که کمک‌یار رویش اجرا می‌شود از حالت استراحت دور نگه می‌دارد. بردن دستی PS5 به حالت استراحت در همه‌ی حالت‌ها کار می‌کند.",
kernellog_categories_explainer: "همه‌ی دسته‌ها در ابتدا نمایش داده می‌شوند. دسته‌های Sony زیرسیستم‌های خود کنسول هستند که روی هر PS5 جیلبریک‌شده، هر payload‌ای که اجرا شود، مدام گزارش می‌نویسند؛ ربطی به ps5upload ندارند. تیکشان را بردارید تا شلوغی کم شود.",
payloads_cached_body: "{kb} KB در حافظه‌ی پنهان محلی دانلود شد.",
payloads_cached_title: "{id} {tag} در حافظه‌ی پنهان ذخیره شد",
payloads_description_catalog_v2: "payloadهای هوم‌بروی PS5 منتخب از سازندگان دیگر. آخرین انتشار را بررسی کنید، یک بار دانلود کنید و سپس با یک کلیک به PS5 بفرستید. نسخه‌ها به‌صورت محلی ذخیره می‌شوند تا بتوانید آن‌ها را روی فلش USB payload هم قرار دهید.",
payloads_description_send_v2: "هر فایل payload PS5 — .elf، .bin، .js، .lua یا .jar (kstuff، لودرهای هوم‌برو سفارشی، اکسپلویت‌های مرحله‌ی مرورگر، اسکریپت‌های افزونه، JARهای BD-JB) — را به PS5 بفرستید. همان روند صفحه‌ی اتصال، فقط با فایلی که خودتان انتخاب می‌کنید. پورت از نوع فایل پیروی می‌کند (.elf/.bin 9021، .jar 9025، .lua 9026، .js 50000)؛ فقط اگر لودر شما روی پورت دیگری گوش می‌دهد آن را تغییر دهید.",
