servers_subtitle: "NAS و سرورهای شما (SMB، FTP، FTPS، SFTP/WebDAV). هر جا که برای یک بازی یا فایل مرور می‌کنید، با ▾ کنار «مرور» از میان آن‌ها انتخاب کنید.",
settings_artwork_cache_explain_v2: "کاورهای بازی جایی که موتور اجرا می‌شود (این کامپیوتر، یا سرور در نسخه‌ی وب) نگه داشته می‌شوند تا به‌جای خواندن هر باره از PS5، فوراً بارگذاری شوند. خودکار تازه می‌شوند و وقتی روی یک کنسول بازی‌ای نصب یا حذف می‌کنید، برای آن کنسول حذف می‌شوند.",
settings_backup_downloaded: "{name} دانلود شد",
settings_backup_hint_v2: "پوسته، فهرست PS5ها، تاریخچه‌ی اعلان‌ها، گزارش فعالیت و دیگر ترجیحات را در یک فایل JSON بسته‌بندی کنید تا پس از پاک کردن حافظه‌ی برنامه یا روی دستگاه دیگری بازیابی کنید. جفت‌سازی کنسول‌ها، مجموعه، رمزهای سرورهای ذخیره‌شده و کتابخانه‌های backport شامل نمی‌شوند.",
settings_backup_restored: "{count} تنظیم بازیابی شد. برای اعمال همه‌ی تغییرات برنامه را مجدداً اجرا کنید.",
settings_backup_saved: "در {path} ذخیره شد",
settings_card_console_rest: "حالت استراحت",
settings_card_console_connect: "اتصال",
auto_bringup_label: "راه‌اندازی خودکار",
auto_bringup_hint: "وقتی لودر (elfldr، پورت 9021) یک PS5 ذخیره‌شده فعال است و کمک‌یار اجرا نمی‌شود، برنامه خودش راه‌اندازی سریع را اجرا می‌کند: فهرست پخش راه‌اندازی اگر تعیین کرده باشید، سپس کمک‌یار، سپس فهرست پخش بارگذار خودکار. هر بار که کنسول روشن می‌شود یک بار؛ پس از حالت استراحت فقط کمک‌یار دوباره فرستاده می‌شود. حدود 90 ثانیه پس از ظاهر شدن لودر صبر می‌کند تا بارگذار خودکار خود کنسول اول کارش را تمام کند. به‌طور پیش‌فرض خاموش است.",
bringup_auto_hint_short: "وقتی لودر PS5 فعال است و کمک‌یار نه، این کار را خودش انجام می‌دهد، حدود 90 ثانیه پس از ظاهر شدن لودر. هر بار که کنسول روشن می‌شود یک بار.",
settings_card_install_fallback: "وقتی PS5 نمی‌تواند بسته‌ای را دریافت کند",
settings_card_system_files: "فایل‌های سیستم",
settings_file_hint_v2: "ترجیحات اصلی (پوسته، زبان، موتور، مسیر ذخیره، پیش‌فرض‌های بارگذاری، دسترسی‌پذیری، نوار کناری) در این فایل JSON بازتاب داده می‌شوند. می‌توانید دستی ویرایشش کنید؛ ویرایش‌ها دفعه‌ی بعد که برنامه را اجرا کنید اعمال می‌شوند. همه چیز را در خود ندارد: برای انتقال همه‌ی ترجیحاتتان از پشتیبان‌گیری / بازیابی استفاده کنید.",
