settings_schedule_label_placeholder_v2: "برچسب (مثلاً پشتیبان‌گیری از ذخیره‌ها)",
settings_updates_browser_note: "این صفحه‌ی وب را موتور ps5upload ارائه می‌دهد و همراه آن به‌روز می‌شود: ایمیج Docker جدید را pull کنید (یا موتور را روی سرورتان به‌روز کنید) و آن را مجدداً اجرا کنید.",
"show_file_list_hint_v2": "فایل‌هایی را که بارگذاری می‌شوند زیر نوار پیشرفت نشان بده. اگر فهرست در پوشه‌هایی با هزاران فایل شلوغ به نظر می‌رسد خاموشش کنید — پیشرفت کلی، سرعت و زمان باقی‌مانده همچنان دیده می‌شوند.",
show_file_list_v2: "نمایش فهرست فایل‌ها هنگام بارگذاری",
stats_description_v2: "مجموع عملیات نمایش‌داده‌شده برای این کنسول. برنامه {count} مورد آخر را نگه می‌دارد، پس موارد قدیمی‌تر شمرده نمی‌شوند. از تاریخچه‌ی محلی محاسبه می‌شود؛ چیزی از دستگاه شما خارج نمی‌شود.",
status_keep_awake_tooltip_v2: "بیدار نگه داشتن روی «همیشه هنگام اتصال» تنظیم شده — کنسول‌های متصل تا وقتی برنامه باز است خودکار به حالت استراحت نمی‌روند. در تنظیمات → کنسول تغییرش دهید.",
update_idle_v2: "هنوز بررسی نشده. با روشن بودن بررسی خودکار، برنامه هنگام اجرا در پس‌زمینه بررسی می‌کند، حداکثر یک بار در روز.",
upload_auto_resume_hint_browser: "اگر بارگذاری در میانه‌ی انتقال قطع شود، وقتی کمک‌یار PS5 دوباره پاسخ دهد از همان جایی که مانده بود ادامه می‌یابد و پیش از تسلیم شدن چند بار دوباره تلاش می‌کند. این صفحه نمی‌تواند خود کمک‌یار را دوباره بفرستد: اگر PS5 مجدداً راه‌اندازی شد، اول آن را دوباره بفرستید. مشکلات جدی مانند پر شدن فضای PS5 همچنان فوراً متوقف می‌شوند. به‌طور پیش‌فرض روشن است.",
upload_wake_for_uploads: "بیدار کردن PS5 برای آپلودِ در انتظار",
upload_wake_for_uploads_hint: "وقتی آپلودی منتظر یک PS5 در حالت استراحت است، سیگنال بیدارباش برایش فرستاده می‌شود و پس از بازگشت کمک‌یار ادامه می‌یابد. فقط برای کنسول‌هایی که بیدار کردن در صفحهٔ اتصال برایشان تنظیم شده است. به‌طور پیش‌فرض روشن است.",
upload_picker_from_ps5_hint: "از یک PS5 دیگر کپی می‌کنید؟ فایل‌ها را در سیستم فایل انتخاب کنید و «ارسال به کنسول دیگر» را بزنید.",
