"minion_remove_note": "حذف، Minion را خاموش می‌کند و آنچه را روی PS5 نگه می‌دارد پاک می‌کند: علاقه‌مندی‌ها و پوشه‌های اخیر فایل‌ها، حافظهٔ پنهان کتابخانهٔ بازی‌ها و گزارش کنترلر. اشتراک‌های شبکه، چیت‌ها و پشتیبان‌ها می‌مانند؛ برنامهٔ رایانه هم از آن‌ها استفاده می‌کند.",
