"connection_send_payload_moved": "می‌خواهید پی‌لود دیگری (kstuff، etaHEN یا هر فایل ‎.elf) بفرستید؟ این کار در پی‌لودها ← ارسال پی‌لود است. این صفحه فقط کمک‌یار PS5Upload را می‌فرستد.",
"connection_send_payload_open": "باز کردن ارسال پی‌لود",
"upload_elf_title": "این یک پی‌لود (‎.elf) است، نه بازی",
"upload_elf_body": "بارگذاری آن فقط فایل را کپی می‌کند. ShadowMount+‎ پوشه‌های بازی (دارای eboot.bin و sce_sys) و ایمیج‌های بازی را برمی‌دارد، هرگز فایل ‎.elf را، پس در صفحهٔ اصلی ظاهر نمی‌شود. برای اجرا، آن را به لودر کنسول بفرستید. چیزی که باید بارگذاری شود برنامهٔ homebrew است که به‌صورت ایمیج ‎.ffpkg یا ‎.exfat، یا پوشه‌ای با eboot.bin عرضه می‌شود.",
"netdoctor.hint.below_test": "این بارگذاری با سرعت {speed} انجام می‌شود، بسیار کمتر از {expected} که آزمون سرعت اندازه گرفت.",
"netdoctor.hint.runs_at": "این بارگذاری با سرعت {speed} انجام می‌شود.",
"netdoctor.hint.cause_source": "چیزی که آن را کند می‌کند خواندن فایل‌ها روی این رایانه است، نه شبکه: درایو USB یا هارد دیسک، پوشهٔ اشتراکی شبکه (NAS) یا باز کردن یک آرشیو کندتر از اتصال است. کپی کردن بازی روی یک SSD داخلی پیش از ارسال، یا بارگذاری فایل‌های آرشیو پس از باز کردن آن، سرعت کامل می‌دهد.",
"netdoctor.hint.cause_disk": "چیزی که آن را کند می‌کند درایو PS5 است، نه شبکه: یک درایو USB خارجی، درایوی که تقریبا پر است یا هزاران فایل کوچک (هر کدام زمان خودش را می‌گیرد) کندتر از آنچه اتصال می‌رساند می‌نویسند. ایمیج بازی (‎.ffpkg یا ‎.exfat) به‌صورت یک فایل ارسال می‌شود.",
"netdoctor.hint.cause_workers": "PS5 هنوز در حال نوشتن چیزهایی است که دریافت کرده و منتظر شبکه نیست. با فایل‌های کوچک زیاد، هر کدام زمان خودش را می‌گیرد؛ ایمیج بازی (‎.ffpkg یا ‎.exfat) به‌صورت یک فایل ارسال می‌شود.",
"netdoctor.hint.cause_cap": "چیزی که آن را کند می‌کند محدودیت سرعت بارگذاری است (حدود {cap} MiB/s، در همین صفحه و در تنظیمات). برای برداشتن آن، آن را روی 0 بگذارید.",
"profile.np.confirm_body_v2": "np-fake-signin فایل‌ها و تنظیمات ورود PlayStation Network را برای {user} روی PS5 می‌نویسد. چیزی به Sony فرستاده نمی‌شود. پس از آن PS5 را دوباره راه بیندازید.",
"profile.np.side_effect": "عارضهٔ شناخته‌شده: پس از آن برخی کنسول‌ها پیش از باز شدن هر بازی می‌خواهند «محدودیت‌های کنسول PS5 موقتاً غیرفعال شود»، و گزینهٔ تنظیمات > کاربران و حساب‌ها > سایر > خروج از حساب ممکن است غیرفعال بماند. برنامه پیش از آن از هر چیزی که np-fake-signin روی PS5 تغییر می‌دهد یک نسخه نگه می‌دارد، پس «لغو ورود» در اینجا آن را برمی‌گرداند.",
"profile.np.backing_up": "در حال نگه‌داشتن نسخه‌ای از تنظیمات فعلی حساب روی PS5…",
"profile.np.backup_failed": "PS5 نتوانست نسخه‌ای از تنظیمات حساب نگه دارد، پس np-fake-signin اجرا نشد. کمک‌یار را با نسخهٔ همین برنامه جایگزین کنید و دوباره امتحان کنید. ({error})",
"profile.np.step_restart_v2": "PS5 را دوباره راه بیندازید. برای بازگرداندن در آینده، «لغو ورود» را در اینجا بزنید و دوباره راه بیندازید.",
"profile.np.undo": "لغو ورود",
"profile.np.undo_hint": "نسخه‌ای از تنظیمات این حساب از پیش از ورود روی PS5 نگه داشته شده است؛ این گزینه آن را برمی‌گرداند.",
"profile.np.undo_confirm_title": "ورود لغو شود؟",
"profile.np.undo_confirm_body": "تنظیمات و فایل‌های {user} را به حالت پیش از اجرای np-fake-signin برمی‌گرداند. پس از آن PS5 را دوباره راه بیندازید. قابلیت‌هایی که به حساب واردشده نیاز دارند، از جمله Remote Play، ممکن است تا ورود دوباره باز نشوند.",
"profile.np.undoing": "در حال بازگرداندن تنظیمات…",
"profile.np.undone": "بازگردانده شد ({count} تنظیم و فایل). برای پایان کار PS5 را دوباره راه بیندازید.",
"profile.np.no_backup": "این حساب تنظیمات الگوی np-fake-signin را دارد (تاریخ تولد 1983-04-12، پرچم بزرگسالِ آفلاین خاموش) و هیچ نسخه‌ای از قبل روی این PS5 نیست، پس برنامه نمی‌تواند آن را لغو کند. اگر PS5 اکنون پیش از باز شدن بازی‌ها می‌خواهد محدودیت‌های کنسول موقتاً غیرفعال شود: تنظیمات > خانواده و کنترل والدین > محدودیت‌های کنسول PS5 (رمز 0000 مگر اینکه آن را عوض کرده باشید) و محدودیت‌ها را آنجا بردارید.",
