"pm_replace_tooltip": "Payload Manager برای پیلودی که دستی اضافه شده نسخه‌ای نگه نمی‌دارد، پس ps5upload نمی‌تواند بفهمد این یکی قدیمی‌تر است یا نه. جایگزینی، نسخهٔ کاتالوگ را به‌جای آن ذخیره می‌کند و جایش را در فهرست بوت حفظ می‌کند؛ پس از آن به‌روزرسانی‌ها اینجا پیشنهاد می‌شوند.",
