"play_setup_play_body": "«بازی» را باز کنید و شروع را بزنید: برنامه کنسول در حال استراحت را بیدار می‌کند، وارد می‌شود و استریم می‌کند. این مرحله با اولین تصویر تیک می‌خورد.",
