"rpg_user_title": "روی PS5 به یک کاربر وارد شوید",
"rpg_user_body": "روی کنسول، کاربری را که با آن بازی می‌کنید انتخاب کنید. لازم نیست کسی روی صفحه بماند، اما کاربر باید وارد شده باشد. از کاربری بدون رمز ورود استفاده کنید: رمز ورود جلوی ورود خودکار هنگام بیدار شدن کنسول را می‌گیرد.",
"rpg_account_title": "به آن کاربر شناسه‌ی حساب بدهید",
"rpg_account_body": "Remote Play با شناسه‌ی حساب جفت می‌شود. کاربری که به PlayStation Network متصل است از قبل یکی دارد؛ برای کاربر آفلاین باید یکی در «کاربران» در بالا تنظیم شود (هر شناسه‌ای کار می‌کند؛ آن را یادداشت کنید، ذخیره‌هایی که بعد از آن ساخته شوند به آن وابسته‌اند).",
"rpg_signin_title": "حساب را به PlayStation Network وارد کنید (آفلاین)",
"rpg_signin_body": "PS5 فقط به حساب واردشده اجازه‌ی استفاده از Remote Play را می‌دهد. اگر تنظیم Remote Play خود کنسول خاکستری است، ورود آفلاین زیر را اجرا کنید (چیزی به Sony فرستاده نمی‌شود)، سپس PS5 را دوباره راه بیندازید. قابل لغو است.",
"rpg_signin_fix": "رفتن به ورود",
"rpg_service_title": "Remote Play را روشن کنید",
"rpg_service_body": "تنظیمات › سیستم › Remote Play › فعال‌سازی Remote Play. برنامه می‌تواند آن را برایتان روشن کند و در فریم‌ور ۱۰.۰۰ و بالاتر آن را برای این کاربر هم مجاز کند.",
"rpg_rest_title": "اجازه دهید PS5 از حالت استراحت بیدار شود",
"rpg_rest_body": "تنظیمات › سیستم › صرفه‌جویی انرژی › قابلیت‌های موجود در حالت استراحت: «به اینترنت متصل بمان» و «فعال‌سازی روشن کردن PS5 از طریق شبکه» را روشن کنید. بدون آن‌ها کنسولِ در حالت استراحت بیدار نمی‌شود و شبکه‌اش پس از چند ثانیه به خواب می‌رود. این گزینه‌ها فقط روی خود کنسول نمایش داده می‌شوند.",
"rpg_pair_title": "این برنامه را با کنسول جفت کنید",
"rpg_pair_body": "اتصال › بیدار کردن و ورود › تنظیم. یک کلیک این برنامه را نزد PS5 ثبت می‌کند (مانند جفت کردن برنامه‌ی PS Remote Play) و کلیدهایش را روی این رایانه نگه می‌دارد. پخش، بیدار کردن و ورود همه از آن‌ها استفاده می‌کنند؛ پس از بازنشانی کنسول یا تغییر کاربر دوباره این کار را انجام دهید.",
"rpg_play_title": "بازی",
"rpg_play_body": "Remote Play را باز کنید و «شروع» را بزنید: برنامه کنسول را اگر در حالت استراحت باشد بیدار می‌کند، وارد می‌شود و پخش را آغاز می‌کند. با دسته‌ای که به این رایانه وصل است، صفحه‌کلید یا لمس بازی کنید. برای استفاده از برنامه‌ی PS Remote Play سونی یا chiaki-ng، در پایین یک PIN درخواست کنید و آن را آنجا وارد کنید.",
"rpg_play_fix": "باز کردن Remote Play",
"rpg_title": "راه‌اندازی Remote Play",
"rpg_progress": "{done} از {n} مرحله‌ی بررسی‌شده انجام شده",
"rpg_on_console": "روی کنسول بررسی کنید",
"rpg_trouble": "اگر هنوز کار نمی‌کند",
"rpg_t_start_q": "دکمهٔ شروع در صفحهٔ «بازی» خاکستری است.",
"rpg_t_start_a": "این برنامه هنوز با آن کنسول جفت نشده است: مرحله‌ی ۶ را انجام دهید (اتصال › بیدار کردن و ورود › تنظیم).",
"rpg_t_pair_q": "راه‌اندازی جفت‌سازی می‌گوید هیچ کاربر واردشده‌ای با حساب فعال وجود ندارد.",
"rpg_t_pair_a": "مراحل ۱ و ۲: روی PS5 به یک کاربر وارد شوید و به آن شناسه‌ی حساب بدهید، سپس دوباره امتحان کنید.",
"rpg_t_grey_q": "تنظیم Remote Play خود PS5 خاکستری است.",
"rpg_t_grey_a": "حساب به PlayStation Network وارد نشده است. ورود آفلاین (مرحله‌ی ۳) را اجرا کنید و PS5 را دوباره راه بیندازید.",
"rpg_t_wake_q": "کنسول بیدار نمی‌شود، یا بیدار می‌شود اما روی صفحه‌ی کاربر می‌ماند.",
"rpg_t_wake_a": "مرحله‌ی ۵ را روی کنسول بررسی کنید. کاربری که رمز ورود دارد جلوی ورود خودکار را می‌گیرد. اگر کنسول بازنشانی شده یا کاربر عوض شده، جفت‌سازی را دوباره تنظیم کنید (مرحله‌ی ۶).",
"rpg_t_black_q": "تصویر سیاه می‌ماند، تکه‌تکه می‌شود، یا صدا خش‌خش می‌کند.",
"rpg_t_black_a": "برای PS5 و این رایانه از اتصال سیمی یا 5 GHz Wi-Fi استفاده کنید و در تنظیمات Remote Play گزینه‌ی 720p یا 30 fps را امتحان کنید. فایروال این رایانه باید به برنامه اجازه‌ی کار در شبکه‌ی محلی را بدهد (Remote Play از پورت‌های TCP و UDP در بازه‌ی 9295–9304 استفاده می‌کند). در مرورگر، از Chrome، Edge یا Safari به‌روز استفاده کنید: تصویر به WebCodecs نیاز دارد.",
"rpg_t_busy_q": "می‌گوید PS5 هنوز دارد جلسه‌ی قبلی را تمام می‌کند، یا کنسول دیگری در حال پخش است.",
"rpg_t_busy_a": "هر بار فقط یک کنسول پخش می‌شود و PS5 پس از پایان یک جلسه تا ۳۰ ثانیه زمان لازم دارد. پخش دیگر را متوقف کنید، کمی صبر کنید، سپس دوباره «شروع» را بزنید.",
"rpg_t_restrict_q": "پس از ورود آفلاین، بازی‌ها می‌خواهند محدودیت‌های کنسول غیرفعال شود.",
"rpg_t_restrict_a": "از «لغو ورود» در این صفحه استفاده کنید و دوباره راه بیندازید، یا محدودیت را در تنظیمات › خانواده و کنترل والدین › محدودیت‌های کنسول PS5 بردارید (رمز 0000 مگر اینکه آن را عوض کرده باشید).",
