"send_title_v2": "بارگذاری و نصب",
"collection.send_many_body_v2": "هر PS5 آنچه کم دارد را می‌گیرد: بستهٔ بازی، یا پوشه، ایمیج یا آرشیو آن، به‌علاوهٔ به‌روزرسانی‌ها و DLCهای تازه‌تر برای بازی‌هایی که دارد. بسته‌ها از این رایانه استریم می‌شوند؛ بقیه در درایوی که در «بارگذاری و نصب» تعیین شده، در پوشهٔ homebrew بارگذاری می‌شوند.",
"first_run_step4_body_v3": "یک فلش USB حاوی ایمیج‌های بازی .ffpkg را به PS5 وصل کنید تا ShadowMount+ آن‌ها را خودکار متصل کند — در «بازی‌ها» ظاهر می‌شوند. برای فرستادن فایل‌های دیگر یا نصب بسته‌های .pkg از «بارگذاری و نصب» استفاده کنید.",
"first_run_go_upload_v2": "باز کردن «بارگذاری و نصب»",
"fpkg.aboutFake_v2": "نتیجه یک بستهٔ جعلی است، بنابراین کنسول قبل از نصب نیاز به پشتیبانی بستهٔ جعلی بارگذاری‌شده دارد: kstuff (نسخه‌ای که پشتیبانی بستهٔ جعلی PS5 دارد)، a53_ppr_install_fast.elf و shadowmountplus.elf، به این ترتیب. «بارگذاری و نصب» همین را کنار دکمه‌های نصب خود می‌گوید.",
"fpkg.openUpload_v2": "باز کردن «بارگذاری و نصب»",
"connection_step3_hint_v3": "«بارگذاری و نصب» را باز کنید و یک پوشهٔ بازی، ایمیج .exfat یا .ffpkg، یا بستهٔ .pkg را رها کنید. ایمیج‌ها و پوشه‌هایی که می‌فرستید در صفحهٔ همان بازی در «بازی‌ها» فهرست می‌شوند، جایی که «اتصال» آن‌ها را روی صفحهٔ اصلی PS5 می‌گذارد.",
"connection_go_upload_v2": "باز کردن «بارگذاری و نصب»",
"netdoctor.speed_cap.on.fix_v2": "اگر لازمش ندارید، محدودیت را در «بارگذاری و نصب» بردارید.",
"payloads_fpkg_ppr_note_v2": "نصب بسته‌های جعلی به a53_ppr_install_fast.elf هم نیاز دارد که در این فهرست نیست: هیچ فایل آماده‌ای برای دانلود منتشر نشده و از کد منبع در GitHub ساخته می‌شود. «بارگذاری و نصب» همهٔ نیازهای بسته‌های جعلی را به ترتیب فهرست می‌کند.",
"fs_extract_next_pkgs_v2": "{n} بسته در آن است: از «بارگذاری و نصب» یا از ردیف خودشان در اینجا نصبشان کنید.",
"game_hub_no_addons_v2": "هیچ بستهٔ DLC برای این عنوان آماده نشده. یکی از «بارگذاری و نصب» بفرستید.",
"game_hub_open_install_v2": "باز کردن «بارگذاری و نصب»",
"bandwidth_cap_off_hint_v3": "بدون محدودیت. اگر بارگذاری‌ها Wi-Fi/LAN را پر می‌کنند و دستگاه‌های دیگر کند می‌شوند، یک محدودیت بگذارید. از بارگذاری بعدی برای همهٔ بارگذاری‌ها اعمال می‌شود؛ از «بارگذاری و نصب»، صف و «فایل‌ها».",
"queue_links_cleared_body_v2": "{n} لینک نصب پس از راه‌اندازی دوباره نگه داشته نشد — لینک‌ها هرگز روی دیسک ذخیره نمی‌شوند. آن‌ها را از «بارگذاری و نصب» دوباره اضافه کنید.",
"game_hub_no_updates_v2": "هیچ بستهٔ به‌روزرسانی برای این عنوان آماده نشده. یکی از «بارگذاری و نصب» بفرستید.",
"pkglib.fpkgsupport.firmware": "بسته‌های جعلی PS5 (PS5 FPKG) هنوز روی فریمورهای جدیدتر از 11.60 پشتیبانی نمی‌شوند: نصب می‌شوند، اما بازی اجرا نمی‌شود. بسته‌های جعلی PS4 مشکلی ندارند.",
"upload_drop_here3": "بسته‌ها، بازی‌ها، ایمیج‌های دیسک، آرشیوها یا هر فایلی را رها یا انتخاب کنید",
"upload_pick_here_mobile3": "بسته‌ها، بازی‌ها، ایمیج‌های دیسک، آرشیوها یا هر فایلی را انتخاب کنید",
"upload_drop_kind_pkg": "بسته‌ها (.pkg، .fpkg): به‌صورت بازی، به‌روزرسانی یا DLC نصب می‌شوند؛ از اینجا استریم یا ابتدا بارگذاری می‌شوند.",
"upload_drop_kind_game": "پوشه‌های بازی و دامپ‌های بازی: روی PS5 کپی می‌شوند؛ می‌توانند در صفحهٔ اصلی قرار گیرند.",
"upload_drop_kind_image": "ایمیج‌های دیسک (.exfat، .ffpkg، .ffpfs، .ffpfsc): روی PS5 کپی می‌شوند؛ قابل اتصال‌اند.",
"upload_drop_kind_archive": "آرشیوها (.zip، .7z، .rar): روی PS5 استخراج می‌شوند.",
"upload_drop_kind_other": "هر فایل یا پوشهٔ دیگر: همان‌طور که هست کپی می‌شود.",
"upload_other_ways": "یا یک بسته نصب کنید:",
"queue_stream_fail_hint": "«استریم و نصب» باعث می‌شود PS5 بسته را از این رایانه بگیرد. اگر مدام شکست خورد، به ps5upload در فایروال این رایانه برای شبکهٔ محلی اجازه دهید تا PS5 به آن برسد، یا از «تلاش دوباره از طریق بارگذاری» استفاده کنید که بسته را ابتدا روی PS5 کپی و سپس نصب می‌کند.",
"err_install_enoent_generic_v2": "نصب‌کنندهٔ سونی نتوانست فایلی را که در طول نصب لازم داشت باز کند (خطای کرنل 0x80020002 = ENOENT). اگر این یک pkg DLC است، بازی پایه هنوز نصب نشده — ابتدا پایه را نصب کنید. در غیر این صورت ممکن است بستهٔ آماده‌شده بین بارگذاری و نصب حذف شده باشد؛ یک‌بار نصب را دوباره تلاش کنید. اگر مدام شکست خورد، آن را با «استریم و نصب» در «بارگذاری و نصب» نصب کنید که بسته را به‌جای کپی کردن روی کنسول، مستقیم از همین رایانه می‌فرستد.",
"upload_convert_first": "اول تبدیل کنید",
